use std::{path::{Path,PathBuf},sync::Arc};use serde_json::{json,Value};use crate::workspace_worker::Workers;
type R<T>=Result<T,String>;
struct Temp {workers:Arc<Workers>,id:String}
impl Drop for Temp{fn drop(&mut self){let _=self.workers.detach(&self.id);}}
fn send(workers:&Workers,id:&str,session:&str,value:Value)->R<Value>{let result=workers.request_session(id,session,&value).map_err(|_|"Пространство отключено. Результат операции не подтверждён.".to_owned())?;if let Some(e)=result["error"].as_str(){return Err(e.into())}result.get("ok").cloned().ok_or("Некорректный ответ пространства".into())}
fn endpoint(workers:&Arc<Workers>,id:&str,path:Option<&Path>,temporary:&mut Vec<Temp>)->R<(String,String)>{if let Some(path)=path{let fd=std::fs::File::open(path).map_err(|_|"Пространство недоступно")?;let temp=uuid::Uuid::new_v4().simple().to_string();workers.attach(&temp,&fd,path).map_err(|e|e.to_string())?;temporary.push(Temp{workers:workers.clone(),id:temp.clone()});let session=workers.session(&temp).map_err(|e|e.to_string())?;Ok((temp,session))}else{Ok((id.to_owned(),workers.session(id).map_err(|e|e.to_string())?))}}
#[cfg(feature="test-hook")] fn copy_barrier(){if let Ok(path)=std::env::var("ATLAS_TEST_COPY_BARRIER"){let dir=Path::new(&path);let _=std::fs::write(dir.join("ready"),b"ready");let start=std::time::Instant::now();while !dir.join("resume").exists()&&start.elapsed()<std::time::Duration::from_secs(10){std::thread::sleep(std::time::Duration::from_millis(10));}}}
#[cfg(not(feature="test-hook"))] fn copy_barrier(){}
pub fn copy(workers:Arc<Workers>,source_id:&str,source_path:Option<PathBuf>,dest_id:&str,dest_path:Option<PathBuf>,object:&str,expected:&str)->R<Value>{if object.is_empty()||!object.chars().all(|c|c.is_ascii_hexdigit()||c=='-')||expected.len()!=64||!expected.chars().all(|c|c.is_ascii_hexdigit()){return Err("Некорректный объект".into())}let mut temporary=Vec::new();let(src,src_session)=endpoint(&workers,source_id,source_path.as_deref(),&mut temporary)?;let(dst,dst_session)=if source_id==dest_id {(src.clone(),src_session.clone())}else{endpoint(&workers,dest_id,dest_path.as_deref(),&mut temporary)?};let before=send(&workers,&src,&src_session,json!({"action":"file-revision","id":object}))?;if before["revision"].as_str()!=Some(expected){return Err("Исходный файл изменился".into())}let download=send(&workers,&src,&src_session,json!({"action":"download-begin","id":object}))?;let stream=download["stream"].as_str().ok_or("Некорректный поток")?.to_owned();let mut upload:Option<String>=None;let result=(||->R<Value>{let started=send(&workers,&dst,&dst_session,json!({"action":"upload-begin","name":download["title"],"size":download["size"]}))?;upload=Some(started["stream"].as_str().ok_or("Некорректный поток")?.to_owned());let mut first=true;loop{let chunk=send(&workers,&src,&src_session,json!({"action":"download-next","stream":stream}))?;send(&workers,&dst,&dst_session,json!({"action":"upload-chunk","stream":upload,"bytes":chunk["bytes"]}))?;if first{first=false;copy_barrier()}if chunk["done"]==true{break}}let after=send(&workers,&src,&src_session,json!({"action":"file-revision","id":object}))?;if after["revision"].as_str()!=Some(expected){return Err("Исходный файл изменился во время копирования".into())}let made=send(&workers,&dst,&dst_session,json!({"action":"upload-finish","stream":upload}))?;upload=None;let board=send(&workers,&dst,&dst_session,json!({"action":"get-board","args":[]}))?;let mut object=board["objects"].as_array().and_then(|v|v.iter().find(|v|v["id"]==made["id"])).cloned().ok_or("Созданный файл не найден")?;let revision=send(&workers,&dst,&dst_session,json!({"action":"object-revision","id":made["id"]}))?;object["revision"]=revision["revision"].clone();Ok(object)})();let _=send(&workers,&src,&src_session,json!({"action":"download-cancel","stream":stream}));if let Some(stream)=upload{let _=send(&workers,&dst,&dst_session,json!({"action":"upload-cancel","stream":stream}));}result}
